def construct_matrix(n):
    # Using 0, 1, 2 to represent I, M, O
    A = [[(i + j) % 3 for j in range(n)] for i in range(n)]
    return A

def check_row_column_balance(A, n):
    counts = [0, 0, 0]
    for i in range(n):
        # Check row i
        row_counts = [0, 0, 0]
        for j in range(n):
            row_counts[A[i][j]] += 1

        if sum(row_counts) != n:
            print(f"Error: Row {i} sum is not n.")
            return False
        if row_counts[0] != n/3 or row_counts[1] != n/3 or row_counts[2] != n/3:
            print(f"Failure: Row {i} distribution is not balanced. Counts: {row_counts}")
            return False

    # Check column balance
    for j in range(n):
        col_counts = [0, 0, 0]
        for i in range(n):
            col_counts[A[i][j]] += 1

        if sum(col_counts) != n:
            print(f"Error: Column {j} sum is not n.")
            return False
        if col_counts[0] != n/3 or col_counts[1] != n/3 or col_counts[2] != n/3:
            print(f"Failure: Column {j} distribution is not balanced. Counts: {col_counts}")
            return False

    print(f"Success: All rows and columns are balanced for N={n}")
    return True

N_test = 9
